sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var licenseFamilyGr = new GlideRecord("license_family");
    licenseFamilyGr.addEncodedQuery("sys_idIN" + current.getValue("application_entitlement"));
    licenseFamilyGr.query();
    var applicationIDs = [];
    while (licenseFamilyGr.next()) {
        applicationIDs.push(licenseFamilyGr.getValue("family_id"));
    }

	//application.sys_idINccd5e764dcd252104f34465061b06a23,7bc5a764dcd252104f34465061b06aa4,8cd5e764dcd252104f34465061b06a81,7bc5a764dcd252104f34465061b06a84,77c5a764dcd252104f34465061b06a83,63c56764dcd252104f34465061b06ae2,50d52b64dcd252104f34465061b06a4b,8cd5e764dcd252104f34465061b06abc,88d5e764dcd252104f34465061b06ac6,7bc5a764dcd252104f34465061b06a6d,7fc5a764dcd252104f34465061b06a4a,14d52b64dcd252104f34465061b06a5f,7bc5a764dcd252104f34465061b06aa3^license_role_type=fulfiller

    //Find roles
    var queryString = "application.sys_idIN" + current.getValue("application_entitlement") + "^license_role_type=" + current.role_type.id;

    if (current.role_type.id.toString() == 'business_stakeholder') {
        queryString += "^ORlicense_role_type=approver";
    }

    var roleGr = new GlideRecord("license_role");
    roleGr.addEncodedQuery(queryString);
    roleGr.query();
    var roles = [];
    while (roleGr.next()) {
        roles.push(roleGr.getValue("name"));
    }

    var licenseDef = new GlideRecord("x_delde_license_subscription");
    if (licenseDef.get(current.sys_id)) {
        licenseDef.setValue("associated_roles", roles.toString());
        licenseDef.update();
    }

})(current, previous);
